window.__finlexDocLoaded(10185,{"id":10185,"articles":[{"id":1000771,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Governs qualitative and non-financial disclosures in SEC registration statements and periodic reports, including Business (Item 101), Risk Factors (Item 105), Cybersecurity (Item 106), MD&A (Item 303), Executive Compensation (Item 402), and Non-GAAP Measures (Item 10(e)).","seq":0},{"id":1000772,"no":"Reg. S-K Item 10(e), 105, 106, 303, 402","heading":"MD&A (Item 303), Non-GAAP Rules (Item 10(e)) & Cybersecurity (106)","text":"• Item 10(e) & Reg G (Non-GAAP Measures): Requires equal or greater prominence for the most directly comparable GAAP measure, quantitative reconciliation, and prohibition of misleading adjustments.\n• Item 303 (MD&A): Liquidity, capital resources, results of operations, known trends/uncertainties, and Critical Accounting Estimates.\n• Item 106 (Cybersecurity, effective Dec 2023): Annual disclosures of cybersecurity risk management, strategy, and board governance (paired with 4-business-day Form 8-K Item 1.05 material incident reporting).\n• Item 105 (Risk Factors) & Item 402 (Executive Compensation & Clawbacks).","seq":1},{"id":1000773,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Item 303 MD&A parallels IFRS Practice Statement 1 (Management Commentary), while Item 10(e) Non-GAAP rules parallel IFRS 18's new Management-Defined Performance Measures (MPMs).","seq":2},{"id":1000774,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (SEC / eCFR (17 CFR Part 229)): https://www.sec.gov/rules-regulations/2003/03/managements-report-internal-control-over-financial-reporting-certification-disclosure-exchange-act\nStatus: in_force.","seq":3}]});
